import{_ as t,H as i,f as a,i as E}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"阶段复习（三） | 一个企业私域AI搜索的问答产品，竟然涉及这么多知识点！","description":"","frontmatter":{},"headers":[{"level":2,"title":"问题一：什么是企业私域 AI 搜索？","slug":"问题一-什么是企业私域-ai-搜索","link":"#问题一-什么是企业私域-ai-搜索","children":[]},{"level":2,"title":"问题二：如何完成意图识别？","slug":"问题二-如何完成意图识别","link":"#问题二-如何完成意图识别","children":[]},{"level":2,"title":"问题三：如何完成 Query 重写？","slug":"问题三-如何完成-query-重写","link":"#问题三-如何完成-query-重写","children":[]},{"level":2,"title":"问题四：如何完成 Query 路由？","slug":"问题四-如何完成-query-路由","link":"#问题四-如何完成-query-路由","children":[]},{"level":2,"title":"问题五：为什么会提到 Agent 设计模式？","slug":"问题五-为什么会提到-agent-设计模式","link":"#问题五-为什么会提到-agent-设计模式","children":[]},{"level":2,"title":"问题六：如何生成企业私域 AI 搜索的回答？","slug":"问题六-如何生成企业私域-ai-搜索的回答","link":"#问题六-如何生成企业私域-ai-搜索的回答","children":[]},{"level":2,"title":"在这个产品中，产品经理的主要任务是什么？","slug":"在这个产品中-产品经理的主要任务是什么","link":"#在这个产品中-产品经理的主要任务是什么","children":[]}],"relativePath":"成为AGI产品经理/阶段复习（三）｜一个企业私域AI搜索的问答产品，竟然涉及这么多知识点！.md","filePath":"成为AGI产品经理/阶段复习（三）｜一个企业私域AI搜索的问答产品，竟然涉及这么多知识点！.md","lastUpdated":1795557342000}'),n={name:"成为AGI产品经理/阶段复习（三）｜一个企业私域AI搜索的问答产品，竟然涉及这么多知识点！.md"};function l(s,e,B,r,A,o){return i(),a("div",null,[...e[0]||(e[0]=[E('<h1 id="阶段复习-三-一个企业私域ai搜索的问答产品-竟然涉及这么多知识点" tabindex="-1">阶段复习（三） | 一个企业私域AI搜索的问答产品，竟然涉及这么多知识点！ <a class="header-anchor" href="#阶段复习-三-一个企业私域ai搜索的问答产品-竟然涉及这么多知识点" aria-label="Permalink to &quot;阶段复习（三） | 一个企业私域AI搜索的问答产品，竟然涉及这么多知识点！&quot;">​</a></h1><p>你好，我是晓蕾。这节课我们来复习怎么做一个企业私域 AI 搜索产品。</p><p>这部分对应的是 8-10 课的内容，我在做知识小卡片的时候发现：原来涉及的知识点有这么多！</p><p>为了让这节课的复习效果更好，我决定变化一下复习思路，先从产品视角重温一下“企业私域AI 搜索”这个产品，这段话会包含很多知识点。</p><p>请看：</p><ul><li><p>企业 AI 搜索产品，相当于一个善于倾听、表达、思维活跃的智者。</p></li><li><p>他首先会倾听你的想法（意图识别），通过上下文将你的问题归类到他早已整理好的问题分类里。这些问题分类可能是基于内容分的，也可能是基于问题的解决方法（要通过访问数据库还是调用搜索引擎等）来分的。</p></li><li><p>然后他转述成自己的语言（Query 重写），使用问题转述、拆解等方法尽可能地从自己的知识库中搜索到对应内容。</p></li><li><p>最后，他拿到这些检索结果后，反复审视（ReAct），重新规划问题解决思路（Plan-and-Solve）；并且在生成回答后还会再核对一下答案（反思）。这个过程会灵活运用各种工具来完成。</p></li></ul><p>上面这段话，很明显包含意图识别、Query 重写、Query 路由，Agent 生成模式这些关键词，甚至在他们的背后，还有需要我们掌握的内容。接下来，我们就一起逐个击破这些知识点。</p><h2 id="问题一-什么是企业私域-ai-搜索" tabindex="-1">问题一：什么是企业私域 AI 搜索？ <a class="header-anchor" href="#问题一-什么是企业私域-ai-搜索" aria-label="Permalink to &quot;问题一：什么是企业私域 AI 搜索？&quot;">​</a></h2><p>某些大型企业客户，也就是 KA（Key Account）客户，往往需要的是一整套解决方案，比如一个完整的企业级知识管理 AI 升级解决方案。听起来和 RAG 差不多，那为什么我们还要拎出来单独讲解呢？企业私域的 AI 搜索和 RAG 有什么区别呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/1.png" alt=""></a></p><h2 id="问题二-如何完成意图识别" tabindex="-1">问题二：如何完成意图识别？ <a class="header-anchor" href="#问题二-如何完成意图识别" aria-label="Permalink to &quot;问题二：如何完成意图识别？&quot;">​</a></h2><p>“意图识别”相当于首先让你的产品学会倾听、理解用户的真实意图。它也是各种“对话类”产品中的必做部分。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/2.png" alt=""></a></p><h2 id="问题三-如何完成-query-重写" tabindex="-1">问题三：如何完成 Query 重写？ <a class="header-anchor" href="#问题三-如何完成-query-重写" aria-label="Permalink to &quot;问题三：如何完成 Query 重写？&quot;">​</a></h2><p>看字面意思，Query 重写就是把用户的输入换一种说法来写。为什么要这么做呢？具体怎么完成呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/3.png" alt=""></a></p><h2 id="问题四-如何完成-query-路由" tabindex="-1">问题四：如何完成 Query 路由？ <a class="header-anchor" href="#问题四-如何完成-query-路由" aria-label="Permalink to &quot;问题四：如何完成 Query 路由？&quot;">​</a></h2><p>Query 路由，简单来说就是为 Query 找到正确的数据源。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/4.png" alt=""></a></p><h2 id="问题五-为什么会提到-agent-设计模式" tabindex="-1">问题五：为什么会提到 Agent 设计模式？ <a class="header-anchor" href="#问题五-为什么会提到-agent-设计模式" aria-label="Permalink to &quot;问题五：为什么会提到 Agent 设计模式？&quot;">​</a></h2><p>为什么我们不能直接把检索结果发给大模型，让它自己生成回答？这有什么难的呢？</p><p>可是，你有没有想过以下几种情况：生成回答前，发现检索结果中没有答案怎么办？生成回答的过程中，有些复杂问题会衍生出来新的问题怎么办？生成回答后，发现回答和检索结果内容不符怎么办？</p><p>这时候，我们就要用到 “Agent 设计模式”这个知识点了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/5.png" alt=""></a></p><h2 id="问题六-如何生成企业私域-ai-搜索的回答" tabindex="-1">问题六：如何生成企业私域 AI 搜索的回答？ <a class="header-anchor" href="#问题六-如何生成企业私域-ai-搜索的回答" aria-label="Permalink to &quot;问题六：如何生成企业私域 AI 搜索的回答？&quot;">​</a></h2><p>这一步需要我们对每一个场景都有深刻的理解。而且，初步确定这些设计模式后，还需要在初始提示词的基础上根据真实使用反复迭代。这个迭代的过程是非常漫长的，可能要经过几个月甚至 1-2 年的迭代。到最后，你可能会发现本质上所有的 Agent 设计模式都是将人类的思维、管理模式以结构化 prompt 的方式告诉大模型来进行规划，并调用工具执行，且不断迭代（反思）的过程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/6.png" alt=""></a></p><h2 id="在这个产品中-产品经理的主要任务是什么" tabindex="-1">在这个产品中，产品经理的主要任务是什么？ <a class="header-anchor" href="#在这个产品中-产品经理的主要任务是什么" aria-label="Permalink to &quot;在这个产品中，产品经理的主要任务是什么？&quot;">​</a></h2><p>最后，我们大致梳理一下产品经理在这个产品中的主要任务。不过注意，千万不要抱着“那我只做这些就好了”的想法。向前迈一步，往往会有更大的收获哦！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/7.png" alt=""></a></p><p>最后，老规矩，提醒一下这几节课的课后作业，如果你还没有做，没关系，这三次作业关系非常密切，强烈推荐你一次完成，绝对酸爽。</p><ul><li>作业一</li></ul><p>将你熟悉的语料，比如你关注的微信公众号内容、知乎问答等按照领域分类，然后将你平时在学习、工作中遇到的问题积累起来，也按照这个领域进行分类；这样你就得到一系列的“问题&lt;-&gt; 意图分类”数据对。</p><p>然后，选定一个大模型（比如智谱的 ChatGLM)，看看模型是否能对你的问题进行准确的意图识别，如果不能，考虑修改你的提示词，直到可以准确识别为止。</p><p>这样你就完成了打造个人私域 AI 搜索的第一步。</p><ul><li>作业二</li></ul><p>对自己的问题做好分类，确定每种类别做合适的 Query 重写方法。之后将自己的知识库按工作、生活、学习这几个种类（或者其他维度）分类，建好知识库（你可以使用 Coze、Dify），然后做一个简单的 Query 路由，试着将你的问题路由到不同知识库进行回答。</p><p>你可以观察：</p><ol><li><p>Query 重写对检索结果的准确率是否有所提升？</p></li><li><p>你的 Query 是否可以正确地被路由到对应的知识库呢？</p></li></ol><ul><li>作业三</li></ul><p>前两次作业，我们完成了个人私域 AI 搜索的意图识别、query 重写、路由。</p><p>在 Coze、Dify 中的最后一步，大语言模型生成回答的时候，请你组合使用 ReAct 模式、Plan-and-Solve 模式、反思模式来回答问题。你也可以尝试一个问题用 “ReAct 模式 + 反思模式” 和 “Plan-and-Solve 模式 + 反思模式” 来分别回答。看看到底哪种模式回答得更准确？</p><p>好啦，欢迎你在留言区分享你的成果，交流遇到的问题。另外，关于专栏，如果你有什么建议或更好的想法，也欢迎你分享在留言区，我一定会关注。如果你觉得这门课有所帮助，欢迎把课程分享给同事或朋友，我们下节复习课见！</p>',43)])])}const u=t(n,[["render",l]]);export{h as __pageData,u as default};
